-- ML-294: warm-up exercises for the Warm-ups tool, edited by super admins in Admin -> Warm-ups.
--
-- Each exercise is written for treble-clef brass (brass band parts - cornet, horn, baritone, euphonium
-- and bass all read the same written notes); the tool shows bass clef (trombone, euphonium) by writing
-- the same exercise down a major 9th, so lip slurs stay on the same harmonics. notes is a JSON list of
-- { p: 'G4' | null (rest), d: 'w'|'h'|'q'|'e', dot?: true } - see public/warmups.js, which the server
-- also uses to check every save (bars must add up; written range F#3-C6).
--
-- The 66 exercises seeded below are original to this app (common teaching patterns: long tones,
-- harmonic-series slurs, intervals, tonguing, five-note scales, short tunes) - no copied material.
-- About 19 minutes of playing at their own tempos, so a 4-5 minute warm-up can vary
-- day to day. Grouping by kind: long-tones 10, lip-slurs 12, flexibility 10, articulation 11, fingers 14, melodic 9.

CREATE TABLE warmup_exercises (
    id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    title TEXT NOT NULL CHECK (length(title) BETWEEN 1 AND 80),
    kind TEXT NOT NULL CHECK (kind IN ('long-tones', 'lip-slurs', 'flexibility', 'articulation', 'fingers', 'melodic')),
    tip TEXT NOT NULL DEFAULT '' CHECK (length(tip) <= 200),
    notes JSONB NOT NULL,
    beats_per_bar SMALLINT NOT NULL DEFAULT 4 CHECK (beats_per_bar BETWEEN 2 AND 6),
    bpm SMALLINT NOT NULL DEFAULT 72 CHECK (bpm BETWEEN 30 AND 200),
    -- Order within the tool (and admin list); gaps of 10 so one can be moved without renumbering.
    sort_order INTEGER NOT NULL DEFAULT 0,
    -- Switched off: kept, but not shown in the tool.
    is_active BOOLEAN NOT NULL DEFAULT true,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX idx_warmup_exercises_order ON warmup_exercises (sort_order, id);


ON CONFLICT (feature_key) DO NOTHING;
