INSERT INTO features (feature_key, name, description, enabled) VALUES
    ('warmups', 'Warm-ups', 'Home screen Warm-ups tool (ML-294): brass warm-up exercises (long tones, lip slurs, flexibility, articulation, finger patterns, easy melodies) on the stave in treble or bass clef, with a metronome that lights the note to play. Exercises are edited in Admin -> Warm-ups.', true)
